import { MarketingLesson, MarketingAssignment } from '../types';
import { QuizQuestion } from '../../../../../types';

/**
 * Digital Marketing Strategy — Module 8 (AI in Digital Marketing) and
 * Module 9 (Capstone and Career), written for complete beginners on a
 * self-paced course. No coding.
 *
 * House style: British spelling, short sentences, an everyday analogy to
 * open every lesson, and the running demo business, Rosie's Bakery in
 * Bristol, wherever an example helps.
 *
 * Accuracy notes (current as of 2026, and the lessons say so where the
 * ground is moving):
 *  - Search engines do not ban AI-assisted content. They reward helpful,
 *    people-first content. Scaled content abuse — mass-producing pages
 *    mainly to game rankings — is the spam violation, whoever or whatever
 *    typed it.
 *  - UK advertising rules (the CAP Code, enforced by the ASA) say ads must
 *    not mislead. That applies to AI-generated imagery that misrepresents
 *    a product, just as it applies to a photograph.
 *  - UK GDPR applies to personal data placed in an AI prompt, the same as
 *    to personal data placed anywhere else.
 *  - No vendor is promoted, no prices are given, no salary figures are
 *    stated, and every number used in an example is labelled illustrative.
 */
